import PropTypes from "prop-types";
import React from "react";

import { bindActionCreators, compose } from "redux";
import { connect } from "react-redux";
import {
  commonRulesMapDisToProps,
  commonRulesReducers,
  commonRulesSelector,
} from "./CommonRuleRedux";
import { getRealValueByType, isValueValid } from "./CommonRuleFunctions";
import applyReducers from "@traveloka/soya-components/lib/legacy/applyReducers";
import ActionModal from "./ActionModal";
import { ModalManager } from "@traveloka/soya-components";
import { NotificationManager } from "@traveloka/soya-components";
import StaticLinkText from "./StaticLinkText/StaticLinkText";

import * as style from "./CommonRule.styles";

class Action extends React.Component {
  constructor(props) {
    super(props);
  }

  handleShowEditActionModal = () => {
    const { action } = this.props;
    ModalManager.show({
      title: `Edit Action`,
      body: (
        <ActionModal
          onCancel={this.handleCancelModalManager}
          onSave={this.handleEditAction}
          existingValue={action}
        />
      ),
      footer: " ",
    });
  };

  handleCancelModalManager = () => {
    ModalManager.dismiss();
  };

  handleRemoveAction = () => {
    const { componentIndex, index, actions } = this.props;
    actions.removeAction(componentIndex, index);
  };

  handleEditAction = (actionValue) => {
    const payload = {};
    let error = false;
    const { componentIndex, index, actions } = this.props;
    const expressionStructure = JSON.parse(
      this.props.ruleStructures.expressionStructure
    );
    for (const i in actionValue) {
      if (i !== "root") {
        for (const j in expressionStructure[actionValue.root].property) {
          if (i === expressionStructure[actionValue.root].property[j]) {
            if (
              isValueValid(
                expressionStructure[actionValue.root].input[j],
                actionValue[i]
              )
            ) {
              payload[i] = getRealValueByType(
                expressionStructure[actionValue.root].input[j],
                actionValue[i]
              );
            } else {
              error = true;
            }
          }
        }
      } else {
        payload.root = actionValue.root;
      }
    }
    if (!error) {
      actions.editAction(componentIndex, index, payload);
      ModalManager.dismiss();
    } else {
      NotificationManager.showError("Input is not valid, please re-check");
    }
  };

  getActionText() {
    const { action, ruleStructures } = this.props;
    const formatterStructure = JSON.parse(ruleStructures.formatterStructure);
    const displayFormat = formatterStructure[action.root].displayFormat;
    const fields = Object.values(formatterStructure[action.root].fields);
    const actionParams = [];
    for (const i in displayFormat) {
      if (
        displayFormat[i].indexOf("{") !== -1 &&
        displayFormat[i].indexOf("}") !== -1
      ) {
        const fieldIdx = parseInt(displayFormat[i].replace(/{|}/g, ""), 10);
        if (!isNaN(fieldIdx) && fieldIdx >= 0) {
          actionParams.push(action[fields[fieldIdx].id]);
        }
      } else {
        // ignore EOF ({-})
        actionParams.push(displayFormat[i]);
      }
    }
    return <span className={style.actionValue}>{actionParams.join("")}</span>;
  }

  render() {
    const text = <span>{this.getActionText()}</span>;
    return (
      <div className={style.actionContent}>
        <StaticLinkText text={text} onClick={this.handleShowEditActionModal} />
        <span className={style.actionButtons}>
          <StaticLinkText
            text="Remove"
            color="#F44336"
            onClick={this.handleRemoveAction}
          />
        </span>
      </div>
    );
  }
}

Action.propTypes = {
  action: PropTypes.object.isRequired,
  actions: PropTypes.object.isRequired,
  componentIndex: PropTypes.number.isRequired,
  index: PropTypes.number.isRequired,
  ruleStructures: PropTypes.string,
};

const mapStateToProps = (state, ownProps) => ({
  ruleStructures: commonRulesSelector.getRuleStructures(state),
});

const mapDispatchToProps = (dispatch, ownProps) => ({
  actions: bindActionCreators(commonRulesMapDisToProps, dispatch),
});

export default compose(
  applyReducers(commonRulesReducers),
  connect(mapStateToProps, mapDispatchToProps)
)(Action);
